create or replace view public.registry_relationship_duplicate_keys with (security_invoker = true) as select r.id as relationship_id, r.source_entity_type, r.source_entity_id, r.source_slug, coalesce(r.source_entity_id::text, concat('slug:', r.source_slug)) as source_comparison_key, r.target_entity_type, r.target_entity_id, r.target_slug, coalesce(r.target_entity_id::text, concat('slug:', r.target_slug)) as target_comparison_key, r.relationship_type, r.relationship_role, r.relationship_status, r.review_status, r.public_safe, r.plain_reason, count(re.evidence_id)::integer as evidence_count from public.registry_entity_relationships r left join public.registry_relationship_evidence re on re.relationship_id = r.id group by r.id;;
